import json,pathlib,gzip,unicodedata,re,collections,sys
R=pathlib.Path(__file__).resolve().parents[1];D=R/'data-snapshots/authored'
raw=json.load(gzip.open(D/'sources/food-basics-list-source.json.gz'))
def emit(p,t):
 if '--check'in sys.argv:assert p.read_text()==t,p
 else:p.write_text(t)
def norm(s):return re.sub('[^a-z0-9+#]','',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower())
common={
'cooking-techniques':'Baking|Boiling|Frying|Grilling|Roasting|Steaming|Simmering|Poaching|Braising|Stewing|Sautéing|Stir frying|Deep frying|Shallow frying|Pan frying|Air frying|Broiling|Smoking|Barbecuing|Pressure cooking|Slow cooking|Microwaving|Blanching|Searing|Caramelizing|Toasting|Pickling|Fermenting|Curing|Drying|Freezing|Marinating|Basting|Brining|Kneading|Whisking|Beating|Folding|Mixing|Chopping|Dicing|Slicing|Mincing|Grating|Peeling|Mashing|Puréeing|Straining|Sifting|Melting|Tempering|Proofing|Scoring|Flambéing|Sous vide|Spatchcocking|Julienne|Zesting|Deboning|Filleting',
'nuts-seeds':'Peanut|Almond|Walnut|Cashew|Pistachio|Hazelnut|Pecan|Brazil nut|Macadamia|Pine nut|Chestnut|Coconut|Acorn|Beech nut|Ginkgo nut|Kola nut|Sunflower seed|Pumpkin seed|Sesame seed|Poppy seed|Chia seed|Flaxseed|Hemp seed|Watermelon seed|Muskmelon seed|Lotus seed|Jackfruit seed|Cacao bean|Coffee bean|Rice|Wheat|Maize|Oat|Barley|Rye|Millet|Sorghum|Quinoa|Amaranth|Buckwheat|Lentil|Chickpea|Soybean|Pea|Kidney bean|Black bean|Mung bean|Fava bean|Lima bean|Cowpea|Fennel seed|Cumin seed|Coriander seed|Mustard seed|Caraway seed|Fenugreek seed|Nigella seed|Cardamom seed|Anise seed|Ajwain|Dill seed|Sacha inchi|Tiger nut|Butternut|Apricot kernel|Bunya nut|Pili nut|Bambara groundnut'
}
# Independently chosen familiar guesses above are retained before source reconciliation.
spec=[]
for key,prompt,scope,refs,wrong,rare in [
('cooking-techniques','Name a cooking or food-preparation technique.','Recognized techniques for cooking, preparing, cutting, mixing, baking or preserving food count. Real public verb/noun forms share an answer. An ingredient, utensil, finished dish or desired texture alone is not a technique.',['https://en.wikipedia.org/wiki/List_of_cooking_techniques','https://www.kingarthurbaking.com/learn/guides/sourdough/glossary','https://www.kingarthurbaking.com/learn/guides/sourdough/bake','https://www.redpathsugar.com/posts/baking-terminology','https://www.ciaprochef.com/prochef-professional-development-courses'],['Fork','Vanilla','Lasagna'],'Nixtamalization'),
('nuts-seeds','Name a culinary nut or a seed people eat.','Culinary nuts and food seeds count, including grains, pulses, spice seeds and nuts that are not botanical nuts. Traditional foods that require preparation count. A named food seed or nut group counts; a botanical class, tree alone, finished sauce or book title does not.',['https://en.wikipedia.org/wiki/List_of_culinary_nuts','https://www.fao.org/4/W0073e/w0073e06.htm','https://openknowledge.fao.org/3/cc5044en/cc5044en.pdf'],['Strawberry fruit','Maple leaf','Sunflower oil'],'Pekea nut')]:
 spec.append(dict(key=key,prompt=prompt,scope=scope,references=refs,familiar=common[key].split('|'),exclude=wrong,rare=rare))
emit(D/'food-basics-specifications.json',json.dumps({'questions':spec},ensure_ascii=False,indent=2)+'\n')
held_cooking={n:'A food/product, ingredient, implement, source heading, cultural model or unverified malformed entry rather than a named technique.' for n in ['al dente','amandine','anti-griddle','aspic','au jus','au poivre','cartouche','casserole','charbroiler','Chinese cooking techniques','consommé','cream','croquette','culinary triangle','cured fish','earth oven','escagraph','flattop grill','foam','fondue','fruit preserves','hibachi','huff paste','meat cooking techniques','mother sauces','maliard','nappage','paste','pellicle','pig roast','pre-ferment','rillettes','roux','Schwenker','shirred eggs','shrivelling','slow cooker','thermal immersion circulator','food steamer','syringe','tandoor','transglutaminase','turkey fryer','Vietnamese cooking techniques']}
ren_cooking={'acidulate':'Acidulating','brine':'Brining','emulsify':'Emulsifying','fillet':'Filleting','flambé':'Flambéing','garnish':'Garnishing','conche':'Conching','egg wash':'Egg washing','score':'Scoring','shuck':'Shucking','spatchcock':'Spatchcocking','truss':'Trussing','whip':'Whipping','zest':'Zesting','purée':'Puréeing','once-a-month cooking (OAMC)':'Once-a-month cooking','microwave cooking':'Microwaving','gratin':'Gratinating','au gratin':'Gratinating','Mongolian barbecue':'Mongolian barbecue cooking','rotisserie':'Rotisserie cooking','straight dough':'Straight-dough method','stuffing':'Stuffing food','supreme':'Supreming','teriyaki':'Teriyaki cooking'}
held_nuts={n:'Classification heading, reference title, morphology text or navigation, not a food nut/seed identity.'for n in ['botanical nuts','Drupes','Gymnosperm','Angiosperm','cold-tolerant','List of edible seeds','The Encyclopedia of Fruit and Nuts','Native American Food Plants: An Ethnobotanical Dictionary','Permaculture plants: a selection','The Book of Edible Nuts']}
ren_nuts={'Beech':'Beech nut','American beech':'American beech nut','European beech':'European beech nut','Chestnuts':'Chestnut','Chinese chestnuts':'Chinese chestnut','Sweet chestnuts':'Sweet chestnut','Hazelnuts':'Hazelnut','American hazelnut':'American hazelnut','Eastern and western beaked hazel':'Beaked hazelnut','European hazelnut':'European hazelnut','Palm nuts':'Palm nut','Almonds':'Almond','Apricot':'Apricot kernel','Betel':'Betel nut','Borneo tallow nuts':'Borneo tallow nut','Canarium':'Canarium nut','Pili nuts':'Pili nut','Cashews':'Cashew','Hickory':'Hickory nut','Mockernut hickory':'Mockernut hickory nut','Pecans':'Pecan','Shagbark hickory':'Shagbark hickory nut','Shellbark hickory':'Shellbark hickory nut','Irvingia':'Irvingia nut','Jack nuts':'Jackfruit seed','Bread nuts':'Breadnut','Cycads':'Cycad seed','Ginkgo nuts':'Ginkgo nut','Araucaria':'Araucaria nut','water chestnut':'Water caltrop','Pine nuts':'Pine nut','Chilgoza pine':'Chilgoza pine nut','Colorado pinyon':'Colorado pinyon nut','Korean pine':'Korean pine nut','Mexican pinyon':'Mexican pinyon nut','Single-leaf pinyon':'Single-leaf pinyon nut','Stone pine':'Stone pine nut','Torreya nuts':'Torreya nut','Chinese nutmeg-yew nuts':'Chinese nutmeg-yew nut','Japanese nutmeg-yew':'Japanese nutmeg-yew nut','California nutmeg tree':'California nutmeg seed','Gnetum nuts':'Gnetum nut','Peanut tree':'Peanut tree seed'}
# Source tree labels are converted only to the edible seed that their source context explicitly names.
manual_cooking='Air frying~Air fry|Broiling~Broil|Slow cooking~Slow cook|Toasting~Toast|Freezing~Freeze|Kneading~Knead|Whisking~Whisk|Beating~Beat|Folding~Fold|Mixing~Mix|Chopping~Chop|Dicing~Dice|Slicing~Slice|Grating~Grate|Peeling~Peel|Mashing~Mash|Straining~Strain|Sifting~Sift|Melting~Melt|Deboning~Debone|Double boiling~Double boil|Blind baking~Bake blind|Docking~Dock|Laminating dough~Dough lamination|Autolyse~Autolysis|Stretch and fold~Stretching and folding|Punching down~Degassing|Rolling out~Rolling|Breading~Bread|Battering~Batter|Butterflying~Butterfly|Flash freezing~Flash freeze|Freeze drying~Freeze dry|Clarifying~Clarify|Churning~Churn|Grinding~Grind|Crushing~Crush|Pounding~Pound|Piping~Pipe|Stirring~Stir|Draining~Drain|Rinsing~Rinse|Washing~Wash|Peeling tomatoes~Skinning tomatoes|Charring~Char|Vacuum packing~Vacuum sealing|Salt baking~Salt crust baking|Stone boiling'
manual_nuts='Sunflower seed|Pumpkin seed~Pepita|Sesame seed~Sesame|Poppy seed|Chia seed~Chia|Flaxseed~Flax seed~Linseed|Hemp seed~Hemp heart|Watermelon seed|Muskmelon seed~Melon seed|Lotus seed|Cacao bean~Cocoa bean|Coffee bean|Rice|Wheat|Maize~Corn|Oat~Oats|Barley|Rye|Millet|Sorghum|Quinoa|Amaranth|Buckwheat|Lentil|Chickpea~Garbanzo bean|Pea|Kidney bean|Black bean|Mung bean~Green gram|Fava bean~Broad bean|Lima bean~Butter bean|Cowpea~Black-eyed pea|Fennel seed|Cumin seed|Coriander seed|Mustard seed|Caraway seed|Fenugreek seed|Nigella seed~Black cumin seed|Cardamom seed|Anise seed~Aniseed|Ajwain~Carom seed|Dill seed|Bambara groundnut|Wild rice|Teff|Fonio|Triticale|Durum wheat|Spelt|Einkorn wheat|Emmer wheat|Khorasan wheat~Kamut|Finger millet~Ragi|Pearl millet|Proso millet|Foxtail millet|Little millet|Kodo millet|Barnyard millet|Pigeon pea~Toor dal|Adzuki bean~Azuki bean|Navy bean~Haricot bean|Pinto bean|Great Northern bean|Cranberry bean~Borlotti bean|Cannellini bean|Lupin bean~Lupini bean|Horse gram|Urad bean~Black gram|Moth bean|Winged bean seed|Jack bean seed|Velvet bean seed|Sword bean seed|Water caltrop~Water chestnut|Celery seed|Nutmeg|Allspice seed|Safflower seed|Egusi~Egusi seed|Cucumber seed|Cantaloupe seed|Squash seed|Papaya seed|Tamarind seed|Pomegranate seed|Grape seed|Bay nut|Chinquapin nut|Breadfruit seed|Chilean pine nut~Monkey puzzle nut'
true_aliases={
'cooking-techniques':{'Baking':['Bake'],'Boiling':['Boil'],'Frying':['Fry'],'Grilling':['Grill'],'Roasting':['Roast'],'Steaming':['Steam'],'Simmering':['Simmer'],'Poaching':['Poach'],'Braising':['Braise'],'Stewing':['Stew'],'Sautéing':['Saute','Sauté','Sauteing'],'Stir frying':['Stir fry'],'Deep frying':['Deep fry'],'Shallow frying':['Shallow fry'],'Pan frying':['Pan fry'],'Smoking':['Smoke'],'Barbecuing':['Barbecue','BBQ cooking'],'Pressure cooking':['Pressure cook'],'Blanching':['Blanch'],'Searing':['Sear'],'Caramelization':['Caramelizing','Caramelising','Caramelisation'],'Pickling':['Pickle'],'Fermentation':['Fermenting','Ferment'],'Curing':['Cure'],'Drying':['Dehydrating','Dehydration','Dry'],'Marination':['Marinating','Marinate'],'Basting':['Baste'],'Mincing':['Mince'],'Puréeing':['Puree','Pureeing'],'Tempering':['Temper'],'Proofing':['Proving','Proof','Prove'],'Sous-vide':['Sous vide cooking'],'Julienne':['Julienning'],'Emulsifying':['Emulsification'],'Gratinating':['Au gratin','Gratin'],'Dough sheeting':['Sheeting dough'],'Hāngī':['Hangi'],'Peeling':['Peel','Peeling tomatoes','Skinning tomatoes'],'Bain-marie':['Double boiling','Double boil'],'Infusion':['Steeping'],'Egg washing':['Egg wash'],'Nixtamalization':['Nixtamalisation'],'Homogenization':['Homogenisation'],'Pasteurization':['Pasteurisation'],'Frosting':['Icing','Decorating with icing'],'Fricassee':['Fricasseeing']},
'nuts-seeds':{'Chilean pine nut':['Monkey puzzle nut'],'Hazelnut':['Filbert','Cobnut'],'Macadamia':['Macadamia nut','Queensland nut'],'Pili nut':['Canarium ovatum'],'Canarium nut':['Canarium'],'Ogbono nut':['Irvingia nut','Irvingia','Irvingia gabonensis','Gabon mango kernel'],'Brazil nut':['Bertholletia excelsa'],'Candlenut':['Kukui nut'],'Almond':['Prunus dulcis'],'Pistachio':['Pistacia vera'],'Sacha inchi':['Inca peanut'],'Walnut':['Walnuts'],'Apricot kernel':['Apricot seed'],'Soybean':['Soya bean','Soy bean'],'Peanut':['Groundnut','Goober'],'Beech nut':['Beechnut'],'Chestnut':['Chestnuts'],'Pine nut':['Pignoli','Pinon'],'Coconut':['Cocos nucifera']}
}
qs=[];ledgers={}
for q in spec:
 k=q['key'];names={};held=[]
 def add(label,als=[],origin=None):
  n=norm(label);r=names.setdefault(n,{'label':label,'aliases':set(),'origins':[]});r['aliases'].update(als);r['origins'].append(origin)
 for row in raw[k]['rows']:
  old=row['label'];holds=held_cooking if k=='cooking-techniques'else held_nuts;rename=ren_cooking if k=='cooking-techniques'else ren_nuts
  if old in holds:held.append({'sourceLabel':old,'reason':holds[old]});continue
  label=rename.get(old,old[:1].upper()+old[1:]);add(label,[],old)
 for row in (manual_cooking if k=='cooking-techniques'else manual_nuts).split('|'):
  label,*als=row.split('~');add(label,als,'Independent public-name supplement')
 # Actual synonyms share a scoring identity, irrespective of source capitalization.
 for label,als in true_aliases[k].items():
  n=norm(label);assert n in names,(k,label)
  for a in als:
   old=norm(a)
   if old in names and old!=n:
    v=names.pop(old);names[n]['aliases'].update([v['label'],*v['aliases']]);names[n]['origins']+=v['origins']
   if old!=n:names[n]['aliases'].add(a)
 owners={n:n for n in names}
 for n,p in names.items():
  for a in p['aliases']:
   z=norm(a);assert z not in owners or owners[z]==n,(k,'alias conflict',a,owners.get(z),n);owners[z]=n
 missing=[s for s in q['familiar']if norm(s)not in owners];assert not missing,(k,missing)
 assert not[s for s in q['exclude']if norm(s)in owners]
 lo={owners[norm(s)]for s in q['familiar'][:6]};common={owners[norm(s)]for s in q['familiar']};rare=owners[norm(q['rare'])];assert rare not in common
 tiers=collections.defaultdict(list)
 for n,p in sorted(names.items()):tiers[str(10 if n in lo else 30 if n in common else 100 if n==rare else 60 if len(p['label'])<=20 else 85)].append({'label':p['label'],'aliases':sorted(a for a in p['aliases']if norm(a)!=n)})
 qs.append(dict(id='authored-'+k,concept=k,family='food',topic='COOKING AND INGREDIENTS',prompt=q['prompt'],scope=q['scope'],format='whole-familiar-food-concept',rationale='One independently selected familiar whole culinary subject. Complete source-list rows are reconciled by meaning, with explicit ingredient/tool/heading holds, public verb forms and identity merges. Source sections, botanical classes and cultural regions never make additional questions.',familiar=q['familiar'],exclude=q['exclude'],references=q['references'],answers=dict(tiers)))
 ledgers[k]={'sourceRows':len(raw[k]['rows']),'held':held,'canonicalAnswers':len(names),'independentFamiliarInputs':len(q['familiar']),'canonicalSourceMap':{p['label']:p['origins']for p in names.values()}}
emit(D/'batches/28-food-basics.json',json.dumps({'version':1,'questions':qs},ensure_ascii=False,indent=2)+'\n');emit(D/'food-basics-review-ledger.json',json.dumps(ledgers,ensure_ascii=False,indent=2)+'\n')
print([(q['id'],sum(map(len,q['answers'].values())))for q in qs])
